/* Handbuchgebundene Suche und Antworten. Kein externer KI-Dienst. */
(function(global){
const stop=new Set('what how does can would should the with that this which where why when are not our your for from have do is it a an and or aber alle als also am an auch auf aus bei bin bitte da das dass dein deine dem den der des die dies diese dieser dieses doch du ein eine einem einen einer eines er es etwas für fuer gibt gut habe haben hat hier ich im in ist ja kann kannst Kapitel mir mit muss nach nun oder sein sie sind so soll sollen sowie über ueber um und uns unser unsere vom von vor warum was welche welcher welches wenn wer wie wird wir wo zu zum zur'.split(' ').map(norm));
function norm(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
const families=[['reliabilitat','reliability','zuverlassigkeit','zuverlassig'],['confidence','konfidenz','aussagewahrscheinlichkeit'],['level','niveau'],['lifetime','lebensdauer','lebenszeit'],['supplier','lieferant','zulieferer','zuliefer'],['component','komponente','bauteil'],['feuchte','feuchtigkeit','humidity'],['strahlen','strahlung','radiation'],['festigkeit','ermudung','wohler','mechanik','mechanisch'],['input','eingang','eingabe'],['output','ausgang','ausgabe'],['failure','ausfall','fehler'],['monitoring','feld','felddaten','feldausfall'],['zusammenspiel','integration','integrieren'],['worst','ungunstig','schlechtfall','grenze','stress'],['sos','systemofsystems'],['lote','lotstelle','verbindungstechnik','avt']];
function words(s){const ignore=new Set(['什么','怎么','如何','为什么','是否','哪些','这个','那个','可以','的','是']);return norm(s).split(' ').flatMap(w=>{if(/[\p{Script=Han}]/u.test(w)){const a=[];for(const chunk of w.match(/[\p{Script=Han}]+|[a-z0-9]+/gu)||[]){if(/[\p{Script=Han}]/u.test(chunk)){for(let i=0;i<chunk.length-1;i++){const token=chunk.slice(i,i+2);if(!ignore.has(token))a.push(token);}}else if(chunk.length>2)a.push(chunk);}return a;}return w.length>2&&!stop.has(w)?[w]:[];});}
function expanded(q){const ws=words(q),res=new Set(ws);for(const w of ws)for(const group of families)if(group.some(t=>w.startsWith(t)||t.startsWith(w)&&w.length>4))group.forEach(t=>res.add(t));return [...res];}
function engine(book,options={}){
 const sections=book.chapters.flatMap(c=>c.sections.map((s,i)=>({chapter:c.id,chapterTitle:c.title,section:i,title:s.title,text:s.text,blocks:s.blocks,terms:words(c.title+' '+s.title+' '+s.text)})));
 function search(query,limit=12){
  const original=words(query),terms=expanded(query);if(!terms.length)return [];
  const weights=new Map(terms.map(w=>[w,.7+3/(1+sections.filter(x=>x.terms.some(t=>t.startsWith(w))).length/10)]));
  return sections.map(s=>{
   const title=norm(s.title),ct=norm(s.chapterTitle),body=norm(s.text);let score=0,matches=0;
   for(const w of terms){const hits=s.terms.filter(t=>t.startsWith(w)||w.length>5&&w.startsWith(t)&&t.length>5).length;if(hits){matches++;score+=Math.min(hits,7)*weights.get(w);if(title.includes(w))score+=12;if(ct.includes(w))score+=4;}}
   if(original.length>1&&original.every(w=>body.includes(w)||title.includes(w)))score+=20;
   if(s.title==='So gehen wir vor')score*=.8;
   if(!s.chapter.startsWith('chapter_'))score*=.75;
   return {...s,score,matches};
  }).filter(x=>x.score>1&&x.matches>0).sort((a,b)=>b.score-a.score).slice(0,limit);
 }
 const faqs=[
 {test:/qualitat.*(zuverlass|reliab)|(?:zuverlass|reliab).*qualitat|unterschied.*qualitat/,answer:'Qualität beschreibt, wie gut ein Produkt Anforderungen und relevante Bedürfnisse erfüllt. Zuverlässigkeit beschreibt, ob eine festgelegte Funktion unter festgelegten Bedingungen über eine festgelegte Dauer oder Nutzung erhalten bleibt. Sie ist ein Qualitätsmerkmal. Ein Wasserkocher kann heute gut funktionieren und dennoch nach wenigen Wochen ausfallen.',refs:[1]},
 {test:/wiederhol.*(pruf|test)|(?:zuliefer|lieferant|supplier).*(pruf|nachweis|zustand|verantwort)|(?:pruf|nachweis).*(zuliefer|supplier)/,answer:'Passende Zuliefernachweise werden übernommen. Prüfe zuerst Ausführung und Version, Funktion, Einbau, Nutzungsprofil, Messort, Musterrepräsentativität und statistische Aussage. Neue Belastungen, geänderte Ausführungen oder verbleibende Lücken benötigen gezielte ergänzende Evidenz. Ein anderes Labor allein ist kein technischer Grund, alle Prüfungen zu wiederholen. Im Feld folgen Monitoring, Ursachenanalyse und Wirksamkeitsnachweis.',refs:[11,12,18,19]},
 {test:/konfidenz|confidence|aussagewahrscheinlichkeit/,answer:'95 Prozent Konfidenzniveau beschreibt die Überdeckungseigenschaft eines statistischen Verfahrens über wiederholte Stichproben unter seinen Annahmen. Es ist weder ein Zuverlässigkeitsziel von 95 Prozent noch die Chance, dass ein Test besteht. Für einen Mindestwert verwenden wir eine vorab festgelegte einseitige untere Grenze. Bei 29 unabhängigen Erfolgen ohne Ausfall liegt diese bei etwa 0,9019 für 95 Prozent Konfidenzniveau.',refs:[14,15]},
 {test:/fmea.*(input|output|vorbereit|zerleg)|(?:input|output).*fmea/,answer:'Beginne mit der Systemgrenze. Erfasse Funktion, Inputs, Outputs, Zustände, Übergänge und zusätzliche Einwirkungen. Zerlege anschließend Funktions- und Signalketten und ordne sie den Architekturelementen zu. Variiere Übergaben: fehlend, falsch, verspätet, veraltet, doppelt oder in falscher Reihenfolge. Die FMEA verfolgt lokale Wirkung, nächsthöhere Ebene und Systemwirkung getrennt.',refs:[3,5,6,8]},
 {test:/fmea/,answer:'Die FMEA startet bei einer möglichen Abweichung einer Funktion oder Schnittstelle und untersucht Ursachen und Wirkungen. Benenne den Fehler konkret mit Zeit und Kontext: „Bereitschaftsmeldung gehört zum alten Auftrag“ ist hilfreicher als „Detektor defekt“. Halte Maßnahmen, Verantwortliche und Wirksamkeitsnachweis fest. Fehlerkombinationen und gemeinsame Ursachen können zusätzliche Methoden wie FTA oder RBD erfordern.',refs:[8,9]},
 {test:/badewanne|bathtub/,answer:'Die Badewannenkurve ist ein Denkmodell für frühe Ausfälle, einen ungefähr konstanten Bereich und spätere Verschleißausfälle. Ob eine Komponente diesen Verlauf zeigt, muss mit geeigneten Daten geprüft werden. Schaubild G zeigt angenommene Beiträge und keine aus Felddaten geschätzte Kurve. Softwaresequenzfehler werden durch dieses Verschleißbild allein nicht erklärt.',refs:[14]},
 {test:/mttf|mtbf|garant.*lebensdauer/,answer:'MTTF ist eine mittlere Zeit bis zum betrachteten Ausfall. MTBF beschreibt mittlere Abstände zwischen betrachteten Ausfällen in einem geeigneten reparierbaren Modell. Beide brauchen eine klare Ereignis- und Zeitdefinition und sind keine garantierte Mindestlebensdauer. Für frühe Ausfälle können Quantile wie B10 und ihre Unsicherheit hilfreicher sein.',refs:[9,14,18]},
 {test:/weibull|b10|zensier|kaplan/,answer:'Das zweiparametrige Weibullmodell verwendet η als Skalenparameter und β als Formparameter. β < 1 beschreibt fallende, β = 1 konstante und β > 1 steigende Hazard Rate. B10 ist die Nutzung, bis zu der im Modell zehn Prozent ausgefallen sind. Noch funktionierende Einheiten liefern rechtszensierte Überlebensinformation und müssen in die Auswertung eingehen. Wenige Ausfälle verlangen besondere Vorsicht bei Schätzung und Konfidenzgrenzen.',refs:[14,15]},
 {test:/nullausfall|stichprobe|musterzahl|wie viele.*(muster|gerate|einheiten)/,answer:'Im binomialen Nullausfallnachweis absolviert jede unabhängige repräsentative Einheit die vollständige definierte Zielnutzung. Bei 95 Prozent einseitigem Konfidenzniveau braucht ein Ziel R ≥ 0,90 mindestens 29 Erfolge ohne Ausfall; R ≥ 0,95 braucht 59, R ≥ 0,99 braucht 299. Ein Gerät mit vielen Zyklen ist keine entsprechende Zahl unabhängiger Geräte. Die Arbeitsmappe enthält einen Rechner für diesen Ansatz.',refs:[15]},
 {test:/beschleunig|arrhenius|halt|hass/,answer:'Beschleunigung braucht einen passenden physikalischen Mechanismus, ein validiertes Übertragungsmodell und geeignete Daten. Eine höhere Temperatur kann auch einen anderen Mechanismus aktivieren. Arrhenius, Peck und mechanische Ansätze beantworten unterschiedliche Fragen. HALT dient der explorativen Schwachstellen- und Grenzsuche; ein darauf abgestimmtes HASS sucht Fertigungsfehler. Daraus folgt allein kein allgemeiner Lebensdauernachweis.',refs:[10,12,15]},
 {test:/mcf|reparier.*(?:ereignis|system)|wiederkehr.*ereignis/,answer:'Die MCF beschreibt die mittlere kumulierte Zahl definierter wiederkehrender Ereignisse pro Einheit bis zur betrachteten Nutzung. Reparierte Einheiten bleiben in der Beobachtung. An jedem Ereigniszeitpunkt addiert die nichtparametrische Schätzung Ereigniszahl geteilt durch beobachtete Einheiten. Die MCF ist keine Ausfallwahrscheinlichkeit und kann größer als eins werden.',refs:[18,19]},
 {test:/crow|amsaa|nhpp|wachstumsmodell/,answer:'Ein Potenzgesetz-NHPP kann wiederkehrende Ereignisse mit zeitabhängiger Intensität beschreiben: M(t) = a·tᵇ und m(t) = a·b·tᵇ⁻¹. Bei b < 1 sinkt die modellierte Intensität, bei b = 1 bleibt sie konstant, bei b > 1 steigt sie. Veränderungen von Nutzung, Meldeweg oder Produktstand beeinflussen Trends. Ein fallender Verlauf allein belegt die Ursache oder Wirksamkeit einer Maßnahme noch nicht.',refs:[18,19]},
 {test:/system of systems|sos|eigenstandig/,answer:'Innerhalb der Produktgrenze bleibt die rekursive Zerlegung in Subsysteme der Ausgangspunkt. Eine SoS-Sicht wird an der übergreifenden Ablaufgrenze geprüft, wenn beteiligte Systeme eigene operative Zwecke und eigenständige Führung haben. Ein Raumwechsel eines Detektors reicht dafür nicht. Dokumentiere eigenen Zweck, Änderungsbefugnis und Änderungsweg statt eine Einordnung nur aus der Komplexität abzuleiten.',refs:[3,6]},
 {test:/stpa/,answer:'STPA ergänzt Fehleranalysen um Steuerung, Freigaben und Rückmeldungen. Betrachte Controller, Befehl, gesteuerten Prozess und Feedback. Ein erforderlicher Befehl kann fehlen, ein unzulässiger gegeben werden, zu früh oder spät kommen oder zu lange wirken. STPA ist eine Gefährdungsanalyse, keine Formel für eine Ausfallwahrscheinlichkeit. Sie ist besonders hilfreich bei problematischen Abläufen trotz intakter Einzelteile.',refs:[9,20]},
 {test:/redundan|gemeinsame ursach|common cause|fehlerbaum|blockdiagramm|rbd|fta/,answer:'Ein Fehlerbaum startet beim unerwünschten Ereignis und sucht Ursachen und Kombinationen. Ein RBD beschreibt die Erfolgsstruktur einer Funktion. Redundanz hilft gegen begründet unabhängige Ausfälle; eine gemeinsame Versorgung, Kühlung oder Softwareursache kann beide Kanäle treffen. Modelliere gemeinsame Ursachen vor einer Parallelrechnung. Schaubild I zeigt FTA und RBD am selben Treppenhauslicht.',refs:[9]},
 {test:/firmware|(?:software|archiv).*update|version|versionsmatrix/,answer:'Ein Update kann Timing, Protokollverhalten, Ressourcen, Leistungsaufnahme und damit Hardwarebelastung verändern. Bewerte die tatsächlich betroffenen Funktionen und Nachweise, halte erlaubte Versionskombinationen fest und führe gezielte Kompatibilitäts- und Regressionstests durch. Eine ungeprüfte Kombination ist nicht freigegeben; zusätzliche Feldbeobachtung allein ersetzt die Freigabe nicht.',refs:[6,13,17]},
 {test:/elektrisch|avt|verbindungstechnik|lotstelle|temperatur|feucht|strahlen|lagerung|mechanisch|festigkeit|falltest|ruttel|vibration|schock/,answer:'Kapitel 12 ordnet allgemeine Hardwareprüfungen nach Mechanismus und Fragestellung: elektrische Belastung, Aufbau- und Verbindungstechnik, Temperaturwechsel, Feuchte und Kondensation, mechanische Festigkeit und Ermüdung, Vibration, Schock und Fall, Strahlenfestigkeit, Lagerung sowie kombinierte Belastungen. Lege Profil, Messort, Funktion während und nach Belastung, Muster, Ausfallkriterium und Abbruchregel vorab fest. Eine bestandene Normprüfung und ein statistischer Lebensdauernachweis sind verschiedene Aussagen.',refs:[10,11,12,15]},
 {test:/integration|zusammenspiel|schlechtfall|worst case|stress.*test|test.*stress/,answer:'Übernimm akzeptierte Komponentenstände und prüfe, ob Spezifikation, Einbau, Schnittstellen und reale Use Cases passen. Wähle Normalfälle, ungünstige zulässige Kombinationen und Wiederanlauf. Variiere zum Beispiel Versorgung, Nachrichtenlaufzeit, alte Auftragskennungen und Last. Dokumentiere Fehlerreaktion und messbaren Abstand zu definierten Grenzen. Explorative Tests außerhalb der Spezifikation sind ein anderer Nachweis als die Erfüllung zulässiger Betriebsfälle.',refs:[5,10,13,16]},
 {test:/mbse|modellbasiert|system engineering|systems engineering/,answer:'MBSE verbindet Systemgrenze, Funktionen, Zustände, Schnittstellen, Architektur, Anforderungen und Nachweise in verknüpften Modellen. Eine Zeichnung allein genügt dafür nicht. Ein geändertes Bereitschaftssignal muss beispielsweise bis zu betroffener Funktion, Versionskombination und Integrationstest verfolgt werden. Ziel ist ein nachvollziehbarer Zusammenhang zwischen Bedarf, Umsetzung und Evidenz.',refs:[3,5,6,7,17]},
 {test:/input|output|systemgrenze|umgebung|zerlegung|signal.*kett|funktion.*kett/,answer:'Grenze das betrachtete System von seiner Umgebung ab. Beschreibe beabsichtigte Inputs und Outputs sowie zusätzliche Einwirkungen auf das System und Rückwirkungen auf die Umgebung. Ergänze Zustand, Vorgeschichte, Timing und Nutzung. Innerhalb dieser Grenze zerlegst du in Subsysteme und wendest dieselbe Betrachtung erneut an. Funktions- und Signalketten helfen, Übergaben zu analysieren, bevor die Hardware- und Softwarearchitektur zugeordnet wird.',refs:[3,4,5,6]},
 {test:/monitor|feldausfall|felddaten|feld|fracas|ursachenanalyse/,answer:'Definiere zuerst das Ereignis und den passenden Nenner: Aufnahme, Betriebsstunde, Gerätejahr oder andere Exposition. Trenne bestätigte Funktionsausfälle, Serviceaustausch und No Fault Found; dokumentiere Version, Alter und Nutzung. Vergleiche geeignete Kohorten mit Unsicherheit. Untersuche konkurrierende Ursachen, prüfe die Maßnahme unter auslösenden Bedingungen und führe das Ergebnis in Anforderungen, FMEA, Modelle und Supplier-Nachweise zurück.',refs:[18,19]},
 {test:/verifikation|validierung|qualifikation|freigabe/,answer:'Verifikation prüft die Erfüllung festgelegter Anforderungen. Validierung prüft, ob das resultierende Produkt im vorgesehenen Kontext die benötigte Anwendung erfüllt. Qualifikation bezeichnet hier die begründete Eignung einer Ausführung für festgelegte Bedingungen und Nutzung. Eine Freigabe bündelt geeignete Evidenz für eine konkrete Konfiguration und einen konkreten Einsatz; sie verspricht keine absolute Ausfallfreiheit.',refs:[11,17]},
 {test:/verfugbarkeit|resilien/,answer:'Verfügbarkeit beschreibt den Anteil beziehungsweise Zeitpunkt, zu dem die definierte Fähigkeit nutzbar ist. Zuverlässigkeit einer Mission bleibt davon getrennt: Ein kurzer Abbruch kann die Mission verlieren, obwohl das Gerät schnell wieder bereitsteht. Resilienz betrachtet Bewältigung einer Störung und Aufrechterhaltung oder Wiederherstellung der Leistung. Eine Pufferung ist nur dann ausreichend, wenn sie für den definierten Ablauf spezifiziert und abgesichert ist.',refs:[1,9,18]},
 ];
 function answer(question,previous=''){
  let q=norm(options.canonicalQuery?options.canonicalQuery(question):question); if(/^(und |was bedeutet das|wie geht das|welches kapitel)/.test(q)&&previous)q=norm(options.canonicalQuery?options.canonicalQuery(previous+' '+question):previous+' '+question);
  if(/wetter|weather|天气|aktien|horoskop|fussball|rezept|politik|passwort|api key/.test(q))return{kind:'unknown',text:'Dazu enthält dieses Handbuch keine belastbare Antwort. Ich helfe dir bei Zuverlässigkeit, Systemzerlegung, Prüfmethoden, Statistik und Feldverbesserung.',refs:[]};
  if(/dosis.*erhoh|schutz.*umgeh|patient.*(?:diagnos|behandel)/.test(q))return{kind:'unknown',text:'Das Handbuch gibt dazu keine konkrete klinische oder produktspezifische Handlungsanweisung. Solche Entscheidungen benötigen die freigegebenen Produkt- und Klinikprozesse. Für die technische Nachweisplanung findest du die methodische Einordnung in Kapitel 16 und 17.',refs:[16,17]};
  const known=faqs.find(f=>f.test.test(q));
  if(known)return{kind:'answer',text:known.answer,refs:known.refs,passages:search(question,3)};
  const found=search(question,3);
  if(!found.length||found[0].score<7)return{kind:'unknown',text:'Ich finde dazu keine ausreichend passende Stelle im Handbuch. Formuliere die Frage mit einem technischen Begriff oder beschreibe Funktion, Nutzung und beobachteten Fehler. Ich erfinde keine Nachweise.',refs:[]};
  const best=found[0],paragraph=best.blocks.find(b=>b.type==='paragraph'&&words(question).some(w=>norm(b.text).includes(w)))||best.blocks.find(b=>b.type==='paragraph');
  return{kind:'passage',text:'Zu deiner Frage finde ich diese Handbuchstelle. Sie ist ein Auszug und keine speziell auf dein Produkt geprüfte Antwort.',quote:paragraph?.text||best.text.slice(0,800),refs:[Number(best.chapter.replace('chapter_',''))].filter(Number.isFinite),passages:found};
 }
 return {search,answer,sections};
}
global.ReliabilityEngine={create:engine,norm,words};
})(typeof window!=='undefined'?window:globalThis);
